const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function getInfoAsync(eeObj) {
    return new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));
  }

  // 1. Geometry & Time Definitions (Bay Dos Gris, Barataria Basin, south of New Orleans)
  const center = ee.Geometry.Point([-90.05, 29.55]);
  const aoi = center.buffer(20000); // 20 km radius

  // Time windows
  const y1 = {start: '1985-06-01', end: '1985-10-31'};
  const y2 = {start: '2024-06-01', end: '2024-10-31'};

  // 2. Data Acquisition & Prep
  function maskLandsatL2(img) {
    const qa = img.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0))     // cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0))     // cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))     // cloud shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0));    // snow
    const scaled = img.select('SR_B.*').multiply(0.0000275).add(-0.2);
    const scId = ee.String(img.get('SPACECRAFT_ID'));
    const isL8 = scId.contains('LANDSAT_8');
    const isL9 = scId.contains('LANDSAT_9');
    const isOli = isL8.or(isL9);
    const optical = ee.Image(ee.Algorithms.If(
      isOli,
      scaled.select(
        ['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'],
        ['Blue','Green','Red','NIR','SWIR1','SWIR2']
      ),
      scaled.select(
        ['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7'],
        ['Blue','Green','Red','NIR','SWIR1','SWIR2']
      )
    ));
    return optical.updateMask(mask);
  }

  function getCollectionForPeriod(period, sensors) {
    let col = ee.ImageCollection(sensors[0]).filterDate(period.start, period.end).filterBounds(aoi);
    for (let i = 1; i < sensors.length; i++) {
      col = col.merge(ee.ImageCollection(sensors[i]).filterDate(period.start, period.end).filterBounds(aoi));
    }
    col = col.map(maskLandsatL2);
    return col;
  }

  async function ensureCollection(period, sensors) {
    let col = getCollectionForPeriod(period, sensors);
    let size = await getInfoAsync(col.size());
    if (size === 0) {
      // widen to May-Nov
      const wider = {start: period.start.slice(0,4) + '-05-01', end: period.end.slice(0,4) + '-11-30'};
      col = getCollectionForPeriod(wider, sensors);
      size = await getInfoAsync(col.size());
      if (size === 0) {
        // full year
        const full = {start: period.start.slice(0,4) + '-01-01', end: period.end.slice(0,4) + '-12-31'};
        col = getCollectionForPeriod(full, sensors);
        size = await getInfoAsync(col.size());
      }
    }
    return {col, size};
  }

  function composite(col) {
    // Median composite
    return col.median().clip(aoi);
  }

  function classifyWaterWetland(img) {
    const green = img.select('Green');
    const red = img.select('Red');
    const nir = img.select('NIR');
    const sw1 = img.select('SWIR1');
    const mndwi = green.subtract(sw1).divide(green.add(sw1));
    const ndvi = nir.subtract(red).divide(nir.add(red));
    const lswi = nir.subtract(sw1).divide(nir.add(sw1));

    const water = mndwi.gt(0.2).and(ndvi.lt(0.2));
    const wetland = ndvi.gt(0.4).and(mndwi.lt(0.1)).and(lswi.gt(0));
    const waterImg = water.updateMask(water).rename('water').toInt();
    const wetlandImg = wetland.updateMask(wetland).rename('wetland').toInt();
    return {waterImg, wetlandImg, ndvi, mndwi, lswi};
  }

  try {
    // Build collections with fallbacks
    const sensors1985 = ['LANDSAT/LT05/C02/T1_L2','LANDSAT/LT04/C02/T1_L2'];
    const sensors2024 = ['LANDSAT/LC09/C02/T1_L2','LANDSAT/LC08/C02/T1_L2'];

    const {col: col1985, size: size1985} = await ensureCollection(y1, sensors1985);
    const {col: col2024, size: size2024} = await ensureCollection(y2, sensors2024);

    if (size1985 === 0 || size2024 === 0) {
      console.log(`1985 Images: ${size1985}`);
      console.log(`2024 Images: ${size2024}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      return;
    }

    const cloud1985 = await getInfoAsync(col1985.aggregate_mean('CLOUD_COVER'));
    const cloud2024 = await getInfoAsync(col2024.aggregate_mean('CLOUD_COVER'));

    const img1985 = composite(col1985);
    const img2024 = composite(col2024);

    // Valid pixel counts (non-null Green band at 1000 m scale)
    const count1985 = await getInfoAsync(
      img1985.select('Green').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).get('Green')
    );
    const count2024 = await getInfoAsync(
      img2024.select('Green').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).get('Green')
    );

    if (!count1985 || !count2024 || count1985 === 0 || count2024 === 0) {
      console.log(`1985 Images: ${size1985} (mean cloud: ${cloud1985 ? cloud1985.toFixed(1) : 'n/a'}%)`);
      console.log(`2024 Images: ${size2024} (mean cloud: ${cloud2024 ? cloud2024.toFixed(1) : 'n/a'}%)`);
      console.log('No valid pixels after masking or null.');
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      return;
    }

    // Classify
    const cls1985 = classifyWaterWetland(img1985);
    const cls2024 = classifyWaterWetland(img2024);

    // Sums at 1000 m scale
    const sum1985 = await getInfoAsync(
      ee.Image.cat(cls1985.waterImg, cls1985.wetlandImg).reduceRegion({
        reducer: ee.Reducer.sum().forEachBand(ee.Image.cat(cls1985.waterImg, cls1985.wetlandImg)),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      })
    );
    const sum2024 = await getInfoAsync(
      ee.Image.cat(cls2024.waterImg, cls2024.wetlandImg).reduceRegion({
        reducer: ee.Reducer.sum().forEachBand(ee.Image.cat(cls2024.waterImg, cls2024.wetlandImg)),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      })
    );

    const w85 = sum1985 ? (sum1985.water || 0) : null;
    const m85 = sum1985 ? (sum1985.wetland || 0) : null;
    const w24 = sum2024 ? (sum2024.water || 0) : null;
    const m24 = sum2024 ? (sum2024.wetland || 0) : null;

    if (w85 === null || m85 === null || w24 === null || m24 === null) {
      console.log(`1985 Images: ${size1985} (mean cloud: ${cloud1985 ? cloud1985.toFixed(1) : 'n/a'}%)`);
      console.log(`2024 Images: ${size2024} (mean cloud: ${cloud2024 ? cloud2024.toFixed(1) : 'n/a'}%)`);
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }

    const den85 = w85 + m85;
    const den24 = w24 + m24;
    if (den85 === 0 || den24 === 0) {
      console.log(`1985 Images: ${size1985} (mean cloud: ${cloud1985 ? cloud1985.toFixed(1) : 'n/a'}%)`);
      console.log(`2024 Images: ${size2024} (mean cloud: ${cloud2024 ? cloud2024.toFixed(1) : 'n/a'}%)`);
      console.log('Zero denominator (no water+wetland).');
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }

    const r85 = w85 / den85;
    const r24 = w24 / den24;
    const delta = r24 - r85;

    console.log(`AOI center: -90.05,29.55; radius: 20km`);
    console.log(`1985 Images: ${size1985} (mean cloud: ${cloud1985 ? cloud1985.toFixed(1) : 'n/a'}%)`);
    console.log(`2024 Images: ${size2024} (mean cloud: ${cloud2024 ? cloud2024.toFixed(1) : 'n/a'}%)`);
    console.log(`1985 Valid px: ${count1985}`);
    console.log(`2024 Valid px: ${count2024}`);
    console.log(`1985 Water px: ${w85}, Wetland px: ${m85}, Ratio: ${r85.toFixed(3)}`);
    console.log(`2024 Water px: ${w24}, Wetland px: ${m24}, Ratio: ${r24.toFixed(3)}`);
    console.log(`Delta (2024-1985): ${delta.toFixed(3)}`);

    if (!isFinite(r85) || !isFinite(r24)) {
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      return;
    }

    if (delta > 0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (e) {
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
